                </div>
                <div>
                  <label className="block font-bold text-slate-700 text-[11px] mb-1">Time Zone</label>
                  <select
                    value={timezone}
                    onChange={(e) => setTimezone(e.target.value)}
                    className="w-full h-9 rounded-lg border border-slate-200 px-2 bg-white text-slate-900 font-bold text-xs"
                  >
                    <option value="Asia/Kolkata">IST (UTC+5:30)</option>
                    <option value="America/New_York">EST (UTC-5)</option>
                    <option value="Europe/London">GMT (UTC+0)</option>
                  </select>
                </div>
              </div>
            )}
          </div>

          {/* Notification Channels */}
          <div className="p-3 bg-white border border-slate-200 rounded-xl space-y-2">
            <label className="block font-extrabold text-slate-900 text-xs">Notification Channels</label>
            <div className="flex items-center gap-4">
              <label className="flex items-center gap-1.5 font-bold text-slate-800 cursor-pointer">
                <input
                  type="checkbox"
                  checked={sendEmail}
                  onChange={(e) => setSendEmail(e.target.checked)}
                  className="rounded text-blue-600 focus:ring-blue-500"
                />
                <Mail className="w-3.5 h-3.5 text-blue-600" /> Send Email
              </label>

              <label className="flex items-center gap-1.5 font-bold text-slate-800 cursor-pointer">
                <input
                  type="checkbox"
                  checked={sendPush}
                  onChange={(e) => setSendPush(e.target.checked)}
                  className="rounded text-blue-600 focus:ring-blue-500"
                />
                <Smartphone className="w-3.5 h-3.5 text-indigo-600" /> Push Notification
              </label>

              <label className="flex items-center gap-1.5 font-bold text-slate-800 cursor-pointer">
                <input
                  type="checkbox"
                  checked={sendInApp}
                  onChange={(e) => setSendInApp(e.target.checked)}
                  className="rounded text-blue-600 focus:ring-blue-500"
                />
                <Bell className="w-3.5 h-3.5 text-emerald-600" /> In-App Feed
              </label>
            </div>
          </div>

          {/* Attachments Section */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label className="block font-extrabold text-slate-900">File Attachments</label>
              <button
                type="button"
                onClick={handleRequestAttachment}
                className="text-blue-600 font-bold hover:underline cursor-pointer flex items-center gap-1"
              >
                <Plus className="w-3.5 h-3.5" /> Attach Resource File
              </button>
            </div>

            {attachments.length > 0 && (
              <div className="space-y-1.5">
                {attachments.map((att) => (
                  <div
                    key={att.id}
                    className="flex items-center justify-between p-2 bg-slate-50 border border-slate-200 rounded-lg text-xs"
                  >
                    <div className="flex items-center gap-2">
                      <Paperclip className="w-4 h-4 text-blue-600" />
                      <span className="font-bold text-slate-900">{att.name}</span>
                      <span className="text-[10px] text-slate-500">({att.sizeMb} MB)</span>
                    </div>

                    <button
                      type="button"
                      onClick={() => handleRemoveAttachment(att.id)}
                      className="text-slate-400 hover:text-red-600 p-1 cursor-pointer"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer Actions */}
          <div className="flex items-center justify-end gap-2 pt-3 border-t border-slate-200 sticky bottom-0 bg-white">
            <Button variant="outline" type="button" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" className="bg-[#2563EB] text-white font-extrabold px-6">
              {editingAnnouncement ? 'Save Changes' : publishOption === 'now' ? 'Publish Announcement' : 'Save Announcement'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* STORAGE CREDIT WARNING MODAL */}
      <Modal
        isOpen={storageNoticeOpen}
        onClose={() => setStorageNoticeOpen(false)}
        title="⚠ Storage Credit Notice"
        subtitle="Instructor storage quota usage notice."
        maxWidth="sm"
      >
        <div className="space-y-4 font-sans text-xs text-left">
          <div className="p-4 bg-amber-50 border border-amber-200 rounded-xl space-y-2 text-amber-900">
            <div className="flex items-center gap-2 font-black text-amber-950">
              <AlertTriangle className="w-5 h-5 text-amber-600 shrink-0" />
              <span>Academy Storage Consumption Notice</span>
            </div>
            <p className="text-amber-800 text-xs leading-relaxed font-medium">
              Files uploaded to announcements are stored in your academy media storage. Storage credits will be deducted based on the uploaded file size. Credits are deducted only after the file upload is completed.
            </p>
          </div>

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-slate-200">
            <Button variant="outline" type="button" onClick={() => setStorageNoticeOpen(false)}>
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleConfirmStorageNotice}
              className="bg-blue-600 text-white font-extrabold px-5"
            >
              Continue &amp; Attach File
            </Button>
          </div>
        </div>
      </Modal>
    </>
  );
};

import React, { useState } from 'react';
import { Download, FileSpreadsheet, FileText, CheckCircle2 } from 'lucide-react';
import { Modal } from '../../../components/ui/Modal';
import { Button } from '../../../components/ui/Button';
import type { AnnouncementItem } from '../store/announcement.store';

export interface ExportAnnouncementsModalProps {
  isOpen: boolean;
  onClose: () => void;
  announcements: AnnouncementItem[];
}

export const ExportAnnouncementsModal: React.FC<ExportAnnouncementsModalProps> = ({
  isOpen,
  onClose,
  announcements,
}) => {
  const [format, setFormat] = useState<'csv' | 'excel' | 'pdf'>('csv');
  const [downloaded, setDownloaded] = useState(false);

  const handleExport = () => {
    setDownloaded(true);
    setTimeout(() => {
      setDownloaded(false);
      onClose();
    }, 1500);
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Export Course Announcements Data"
      subtitle="Download announcement delivery records, read receipts, and timestamps."
      maxWidth="sm"
    >
      <div className="space-y-4 font-sans text-xs text-left">
        <div className="space-y-2">
          <label className="block font-extrabold text-slate-900">Select Export Format</label>
          <div className="grid grid-cols-3 gap-2">
            {[
              { id: 'csv', label: 'CSV Spreadsheet', icon: FileSpreadsheet },
              { id: 'excel', label: 'Excel Workbook', icon: FileSpreadsheet },
              { id: 'pdf', label: 'PDF Document', icon: FileText },
            ].map((item) => {
              const Icon = item.icon;
              const isSelected = format === item.id;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => setFormat(item.id as any)}
                  className={`p-3 rounded-xl border text-center space-y-1 transition-all cursor-pointer ${
                    isSelected
                      ? 'bg-blue-600 text-white border-blue-600 shadow-xs'
                      : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50'
                  }`}
                >
                  <Icon className="w-5 h-5 mx-auto" />
                  <span className="font-bold text-[11px] block">{item.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        <div className="p-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-600 font-medium text-[11px]">
          Exporting <strong>{announcements.length} announcement records</strong> including status badges, author metadata, read conversion rates, and attachment counts.
        </div>

        {downloaded && (
          <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-xl flex items-center gap-2 text-emerald-800 font-bold">
            <CheckCircle2 className="w-4 h-4 text-emerald-600 shrink-0" />
            <span>Export generated successfully! Download started.</span>
          </div>
        )}

        <div className="flex items-center justify-end gap-2 pt-3 border-t border-slate-200">
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button
            onClick={handleExport}
            className="bg-[#2563EB] text-white font-extrabold px-6"
            leftIcon={<Download className="w-4 h-4" />}
          >
            Export Now
          </Button>
        </div>
      </div>
    </Modal>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import {
  Megaphone,
  Plus,
  Download,
  BarChart3,
  BookOpen,
} from 'lucide-react';
import { Card } from '../../../components/ui/Card';
import { Button } from '../../../components/ui/Button';
import { Badge } from '../../../components/ui/Badge';
import { Skeleton } from '../../../components/ui/Skeleton';
import { usePlatformStore } from '../../../store/usePlatformStore';

import { useAnnouncementStore, type AnnouncementItem } from '../store/announcement.store';
import { AnnouncementSummaryCards } from '../components/AnnouncementSummaryCards';
import { AnnouncementFilters } from '../components/AnnouncementFilters';
import { AnnouncementCard } from '../components/AnnouncementCard';
import { CreateAnnouncementModal } from '../components/CreateAnnouncementModal';
import { AnnouncementDetailModal } from '../components/AnnouncementDetailModal';
import { AnnouncementAnalyticsModal } from '../components/AnnouncementAnalyticsModal';
import { ExportAnnouncementsModal } from '../components/ExportAnnouncementsModal';

export const GlobalAnnouncementsPage: React.FC = () => {
  const courses = usePlatformStore((state) => state.courses || []);

  const announcements = useAnnouncementStore((state) => state.announcements);
  const addAnnouncement = useAnnouncementStore((state) => state.addAnnouncement);
  const updateAnnouncement = useAnnouncementStore((state) => state.updateAnnouncement);
  const deleteAnnouncement = useAnnouncementStore((state) => state.deleteAnnouncement);
  const duplicateAnnouncement = useAnnouncementStore((state) => state.duplicateAnnouncement);
  const publishAnnouncement = useAnnouncementStore((state) => state.publishAnnouncement);
  const togglePinAnnouncement = useAnnouncementStore((state) => state.togglePinAnnouncement);
  const archiveAnnouncement = useAnnouncementStore((state) => state.archiveAnnouncement);
  const addComment = useAnnouncementStore((state) => state.addComment);
  const deleteComment = useAnnouncementStore((state) => state.deleteComment);
  const toggleCommentLike = useAnnouncementStore((state) => state.toggleCommentLike);

  // Filters State
  const [selectedCourseFilter, setSelectedCourseFilter] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [sortBy, setSortBy] = useState('newest');

  // Modal States
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [editingAnnouncement, setEditingAnnouncement] = useState<AnnouncementItem | null>(null);
  const [activeDetailAnnouncement, setActiveDetailAnnouncement] = useState<AnnouncementItem | null>(null);
  const [isAnalyticsOpen, setIsAnalyticsOpen] = useState(false);
  const [isExportOpen, setIsExportOpen] = useState(false);

  // Loading state
  const [isLoading, setIsLoading] = useState(true);
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 200);
    return () => clearTimeout(timer);
  }, []);

  const filteredAnnouncements = useMemo(() => {
    let list = [...announcements];

    if (selectedCourseFilter !== 'all') {
      list = list.filter((a) => a.courseUuid === selectedCourseFilter);
    }

    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      list = list.filter(
        (a) =>
          a.title.toLowerCase().includes(q) ||
          a.summary.toLowerCase().includes(q) ||
          a.content.toLowerCase().includes(q)
      );
    }

    if (categoryFilter !== 'All') {
      list = list.filter((a) => a.category === categoryFilter);
    }

    if (statusFilter === 'published') {
      list = list.filter((a) => a.status === 'published');
    } else if (statusFilter === 'scheduled') {
      list = list.filter((a) => a.status === 'scheduled');
    } else if (statusFilter === 'draft') {
      list = list.filter((a) => a.status === 'draft');
    } else if (statusFilter === 'pinned') {
      list = list.filter((a) => a.isPinned);
    } else if (statusFilter === 'archived') {
      list = list.filter((a) => a.status === 'archived');
    }

    list.sort((a, b) => {
      if (a.isPinned && !b.isPinned) return -1;
      if (!a.isPinned && b.isPinned) return 1;

      if (sortBy === 'newest') return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
      if (sortBy === 'oldest') return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime();
      if (sortBy === 'most_read') return b.viewsCount - a.viewsCount;
      if (sortBy === 'recently_updated') return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
      return 0;
    });

    return list;
  }, [announcements, selectedCourseFilter, searchQuery, categoryFilter, statusFilter, sortBy]);

  // Metrics
  const total = announcements.length;
  const published = announcements.filter((a) => a.status === 'published').length;
  const scheduled = announcements.filter((a) => a.status === 'scheduled').length;
  const drafts = announcements.filter((a) => a.status === 'draft').length;
  const pinned = announcements.filter((a) => a.isPinned).length;
  const archived = announcements.filter((a) => a.status === 'archived').length;

  const readRatePercent =
    published > 0
      ? Math.round(
          announcements
            .filter((a) => a.status === 'published')
            .reduce((sum, a) => {
              const readCount = a.readReceipts.filter((r) => r.isRead).length;
              const tot = a.readReceipts.length || 1;
              return sum + (readCount / tot) * 100;
            }, 0) / published
        )
      : 0;

  const unreadStudentsCount = announcements.reduce((sum, a) => {
    return sum + a.readReceipts.filter((r) => !r.isRead).length;
  }, 0);

  const handleSaveForm = (data: any) => {
    if (editingAnnouncement) {
      updateAnnouncement(editingAnnouncement.id, data);
    } else {
      addAnnouncement(data);
    }
  };

  return (
    <div className="space-y-6 text-left font-sans pb-16">
      {/* HEADER */}
      <Card padding="md" className="bg-white border border-slate-200/90 shadow-2xs">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-black text-slate-900 tracking-tight">Global Academy Announcements</h1>
              <Badge variant="info" size="sm" className="font-bold">
                {total} Announcements
              </Badge>
            </div>
            <p className="text-xs text-slate-500 font-medium mt-0.5">
              Manage and dispatch announcements across all academy courses from a centralized dashboard.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2 shrink-0">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setIsExportOpen(true)}
              className="h-9 text-xs font-semibold text-slate-700"
              leftIcon={<Download className="w-4 h-4 text-blue-600" />}
            >
              Export
            </Button>

            <Button
              variant="outline"
              size="sm"
              onClick={() => setIsAnalyticsOpen(true)}
              className="h-9 text-xs font-semibold text-slate-700"
              leftIcon={<BarChart3 className="w-4 h-4 text-indigo-600" />}
            >
              Analytics
            </Button>

            <Button
              size="sm"
              onClick={() => {
                setEditingAnnouncement(null);
                setIsCreateModalOpen(true);
              }}
              className="h-9 bg-[#2563EB] text-white font-extrabold text-xs px-4 hover:bg-blue-700"
              leftIcon={<Plus className="w-4 h-4 stroke-[3]" />}
            >
              Create Announcement
            </Button>
          </div>
        </div>
      </Card>

      {/* SUMMARY CARDS */}
      <AnnouncementSummaryCards
        total={total}
        published={published}
        scheduled={scheduled}
        drafts={drafts}
        pinned={pinned}
        archived={archived}
        readRatePercent={readRatePercent}
        unreadStudentsCount={unreadStudentsCount}
        onFilterByStatus={(st) => setStatusFilter(st)}
      />

      {/* COURSE SELECTOR BAR & FILTERS */}
      <div className="space-y-3">
        <div className="p-3 bg-white border border-slate-200/90 rounded-2xl flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 shadow-2xs font-sans text-xs">
          <div className="flex items-center gap-2">
            <BookOpen className="w-4 h-4 text-blue-600" />
            <span className="font-extrabold text-slate-900">Filter by Course:</span>
          </div>

          <select
            value={selectedCourseFilter}
            onChange={(e) => setSelectedCourseFilter(e.target.value)}
            className="h-9 px-3 rounded-xl border border-slate-200 bg-slate-50 text-slate-900 font-bold text-xs focus:ring-2 focus:ring-blue-500/20"
          >
            <option value="all">All Academy Courses ({courses.length})</option>
            {courses.map((c) => (
              <option key={c.id} value={c.id}>
                {c.title}
              </option>
            ))}
          </select>
        </div>

        <AnnouncementFilters
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          statusFilter={statusFilter}
          onStatusChange={setStatusFilter}
          categoryFilter={categoryFilter}
          onCategoryChange={setCategoryFilter}
          sortBy={sortBy}
          onSortChange={setSortBy}
          onReset={() => {
            setSelectedCourseFilter('all');
            setSearchQuery('');
            setStatusFilter('all');
            setCategoryFilter('All');
            setSortBy('newest');
          }}
        />
      </div>

      {/* ANNOUNCEMENTS CARDS LIST */}
      {isLoading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <Card key={i} padding="md" className="space-y-3 bg-white border border-slate-200">
              <Skeleton className="h-5 w-2/3" />
              <Skeleton className="h-4 w-full" />
            </Card>
          ))}
        </div>
      ) : filteredAnnouncements.length > 0 ? (
        <div className="space-y-3">
          {filteredAnnouncements.map((anc) => (
            <AnnouncementCard
              key={anc.id}
              announcement={anc}
              onOpen={(id) => {
                const found = announcements.find((a) => a.id === id);
                if (found) setActiveDetailAnnouncement(found);
              }}
              onEdit={(anc) => {
                setEditingAnnouncement(anc);
                setIsCreateModalOpen(true);
              }}
              onDuplicate={duplicateAnnouncement}
              onPublish={publishAnnouncement}
              onTogglePin={togglePinAnnouncement}
              onArchive={archiveAnnouncement}
              onDelete={deleteAnnouncement}
            />
          ))}
        </div>
      ) : (
        <Card padding="lg" className="bg-white border border-slate-200 text-center py-14 space-y-4 font-sans">
          <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mx-auto">
            <Megaphone className="w-8 h-8" />
          </div>
          <div className="space-y-1 max-w-md mx-auto">
            <h3 className="text-base font-extrabold text-slate-900">No Announcements Found</h3>
            <p className="text-xs text-slate-500 font-medium">
              Create an announcement and select your target course to notify students.
            </p>
          </div>
          <Button
            onClick={() => {
              setEditingAnnouncement(null);
              setIsCreateModalOpen(true);
            }}
            className="bg-[#2563EB] text-white font-extrabold text-xs px-6"
            leftIcon={<Plus className="w-4 h-4" />}
          >
            Create Announcement
          </Button>
        </Card>
      )}

      {/* MODALS */}
      <CreateAnnouncementModal
        isOpen={isCreateModalOpen}
        onClose={() => {
          setIsCreateModalOpen(false);
          setEditingAnnouncement(null);
        }}
        onSubmit={handleSaveForm}
        editingAnnouncement={editingAnnouncement}
      />

      <AnnouncementDetailModal
        isOpen={!!activeDetailAnnouncement}
        onClose={() => setActiveDetailAnnouncement(null)}
        announcement={activeDetailAnnouncement}
        onAddComment={(announcementId, content) =>
          addComment(
            announcementId,
            { uuid: 'inst-1', name: 'Dr. Rajesh Sharma', role: 'instructor' },
            content
          )
        }
        onDeleteComment={deleteComment}
        onLikeComment={toggleCommentLike}
      />

      <AnnouncementAnalyticsModal
        isOpen={isAnalyticsOpen}
        onClose={() => setIsAnalyticsOpen(false)}
        announcements={announcements}
      />

      <ExportAnnouncementsModal
        isOpen={isExportOpen}
        onClose={() => setIsExportOpen(false)}
        announcements={announcements}
      />
    </div>
  );
};

