                    })}
                  </div>

                  {/* FILE UPLOAD CONFIGURATION CONTROLS */}
                  {isFileUploadEnabled && (
                    <div className="p-4 bg-[#F8FAFC] border border-[#E2E8F0] rounded-[14px] space-y-4">
