import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useNavigate } from "react-router-dom";
import { CheckCircle2 } from "lucide-react";
import { setupPasswordSchema, type SetupPasswordSchemaType } from "../schemas/auth.schema";
import { useSetupPassword } from "../hooks/useSetupPassword";
import { PasswordField } from "./PasswordField";
import { PasswordStrength } from "./PasswordStrength";
import { Button } from "../../../components/ui/Button";
import { Alert } from "../../../components/ui/Alert";
import { formatAuthError } from "../utils/auth-errors";
import { AUTH_MESSAGES } from "../constants/auth.constants";

export interface PasswordSetupFormProps {
  token: string;
}

export const PasswordSetupForm: React.FC<PasswordSetupFormProps> = ({ token }) => {
  const navigate = useNavigate();
  const [apiError, setApiError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const setupPasswordMutation = useSetupPassword();

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors },
  } = useForm<SetupPasswordSchemaType>({
    resolver: zodResolver(setupPasswordSchema),
    defaultValues: {
      password: "",
      confirm_password: "",
    },
  });

  const passwordValue = watch("password");

  const onSubmit = (data: SetupPasswordSchemaType) => {
    setApiError(null);
    setupPasswordMutation.mutate(
      {
        token,
        password: data.password,
        confirm_password: data.confirm_password,
      },
      {
        onSuccess: () => {
          setSuccessMessage(AUTH_MESSAGES.PASSWORD_SET_SUCCESS);
          setTimeout(() => {
            navigate("/login", { replace: true });
          }, 2000);
        },
        onError: (err) => {
          setApiError(formatAuthError(err));
        },
      }
    );
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-4 text-left">
      {apiError && (
        <Alert type="error" onClose={() => setApiError(null)}>
          {apiError}
        </Alert>
      )}

      {successMessage && (
        <Alert type="success" title="Success">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-4 h-4 text-[#16A34A]" />
            <span>{successMessage}</span>
          </div>
        </Alert>
      )}

      <PasswordField
        label="New Password"
        placeholder="••••••••"
        autoComplete="new-password"
        error={errors.password?.message}
        {...register("password")}
      />

      <PasswordStrength password={passwordValue} />

      <PasswordField
        label="Confirm Password"
        placeholder="••••••••"
        autoComplete="new-password"
        error={errors.confirm_password?.message}
        {...register("confirm_password")}
      />

      <Button
        type="submit"
        size="lg"
        className="w-full mt-4"
        isLoading={setupPasswordMutation.isPending}
        disabled={Boolean(successMessage)}
      >
        Set New Password
      </Button>
    </form>
  );
};

import { AxiosError } from "axios";
import type { ApiErrorResponse } from "../../../types/api.types";

export function formatAuthError(error: unknown): string {
  if (typeof error === "string") return error;

  if (error && typeof error === "object" && "message" in error && typeof (error as any).message === "string") {
    const errObj = error as AxiosError<ApiErrorResponse>;
    if (errObj.response?.data) {
      const data = errObj.response.data;
      if (data.detail) return data.detail;
      if (data.message) return data.message;
      if (data.errors && typeof data.errors === "object") {
        const firstKey = Object.keys(data.errors)[0];
        const val = data.errors[firstKey];
        if (Array.isArray(val) && val.length > 0) return val[0];
        if (typeof val === "string") return val;
      }
    }
    return errObj.message || "An unexpected error occurred.";
  }

  return "An unexpected error occurred. Please try again.";
}

import React, { useRef, useLayoutEffect, useState, useEffect } from 'react';

export interface AutoFitTextContainerProps {
  text?: string;
  maxFontSize: number;
  fontFamily?: string;
  fontWeight?: string | number;
  fontStyle?: string;
  fontColor?: string;
  textAlign?: 'left' | 'center' | 'right';
  isUnderline?: boolean;
  letterSpacing?: number;
  opacity?: number;
  className?: string;
  style?: React.CSSProperties;
  onClick?: (e: React.MouseEvent) => void;
  onMouseDown?: (e: React.MouseEvent) => void;
  children?: React.ReactNode;
}

/**
 * Container-Safe Dynamic Field Auto Font Fit Component.
 * Guarantees dynamic text NEVER overflows outside its assigned container boundaries.
 * - Enforces single-line text (no line breaks / no wrapping).
 * - Uses ResizeObserver and font loading triggers for instant pixel-perfect calculation.
 * - Recalculates dynamically in real-time on value or dimension changes.
 */
export const AutoFitTextContainer: React.FC<AutoFitTextContainerProps> = ({
  text = '',
  maxFontSize,
  fontFamily = 'Inter',
  fontWeight = '600',
  fontStyle = 'normal',
  fontColor = '#0F172A',
  textAlign = 'center',
  isUnderline = false,
  letterSpacing = 0,
  opacity = 1,
  className = '',
  style = {},
  onClick,
  onMouseDown,
  children,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);
  const [fittedFontSize, setFittedFontSize] = useState<number>(maxFontSize);

  const calculateFit = () => {
    const container = containerRef.current;
    const textSpan = textRef.current;
    if (!container || !textSpan || !text) return;

    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;

    if (containerWidth <= 0 || containerHeight <= 0) return;

    // Calculate candidate font size based on container height (85% container height ceiling)
    let size = Math.min(maxFontSize, Math.max(10, Math.floor(containerHeight * 0.85)));
    textSpan.style.fontSize = `${size}px`;

    const scrollWidth = textSpan.scrollWidth;

    // If text exceeds container width, scale font size down proportionally to fit
    if (scrollWidth > containerWidth && scrollWidth > 0) {
      const widthRatio = containerWidth / scrollWidth;
      size = Math.max(8, Math.floor(size * widthRatio));
      textSpan.style.fontSize = `${size}px`;

      // Iterative step down to strictly guarantee zero container overflow
      while (textSpan.scrollWidth > container.clientWidth && size > 8) {
        size -= 1;
        textSpan.style.fontSize = `${size}px`;
      }
    }

    setFittedFontSize(size);
  };

  useLayoutEffect(() => {
    calculateFit();
  }, [
    text,
    maxFontSize,
    fontFamily,
    fontWeight,
    fontStyle,
    letterSpacing,
    style?.width,
    style?.height,
  ]);

  // Recalculate dynamically when container resizes or Google fonts finish loading
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const observer = new ResizeObserver(() => {
      calculateFit();
    });

    observer.observe(container);

    if (document.fonts) {
      document.fonts.ready.then(() => {
        calculateFit();
      });
    }

    return () => {
      observer.disconnect();
    };
  }, [text, maxFontSize]);

  const justifyContent =
    textAlign === 'left' ? 'flex-start' : textAlign === 'right' ? 'flex-end' : 'center';

  const showText = Boolean(text && text.trim().length > 0);

  return (
    <div
      ref={containerRef}
      onClick={onClick}
      onMouseDown={onMouseDown}
      className={`relative overflow-hidden flex items-center ${className}`}
      style={{
        justifyContent,
        opacity,
        boxSizing: 'border-box',
        ...style,
      }}
    >
      {showText && (
        <span
          ref={textRef}
          className="whitespace-nowrap inline-block select-none transition-all duration-75"
          style={{
            fontSize: `${fittedFontSize}px`,
            fontFamily,
            fontWeight,
            fontStyle,
            color: fontColor,
            textAlign,
            textDecoration: isUnderline ? 'underline' : 'none',
            letterSpacing: `${letterSpacing}px`,
            lineHeight: 1.1,
            maxWidth: '100%',
            maxHeight: '100%',
            overflow: 'hidden',
          }}
        >
          {text}
        </span>
      )}
      {children}
    </div>
  );
};

