  };

  const addSubheadingElement = () => {
    addElement({
      type: 'text',
      label: 'Subheading',
      text: 'For Exceptional Merit & Outstanding Performance',
      x: 50,
      y: 40,
      width: 65,
      height: 40,
      fontFamily: 'Inter',
      fontSize: 16,
      fontWeight: 600,
      fontColor: '#475569',
      textAlign: 'center',
    });
  };

  const addBodyElement = () => {
    addElement({
      type: 'text',
      label: 'Paragraph Text',
      text: 'Has successfully fulfilled all curriculum requirements and passed final assessments.',
      x: 50,
      y: 60,
      width: 80,
      height: 50,
      fontFamily: 'Roboto',
      fontSize: 14,
      fontWeight: 400,
      fontColor: '#64748B',
      textAlign: 'center',
