      {/* TOP STUDIO TOOLBAR (DESKTOP & MOBILE DEDICATED LAYOUTS) */}
      <header className="bg-white border-b border-slate-200 px-3 sm:px-4 py-2.5 shrink-0 text-slate-900 sticky top-0 z-20 shadow-2xs">
