import React, { useEffect, useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { motion, AnimatePresence } from 'framer-motion';
import {
  X,
  Layers,
  Clock,
  Lock,
  Check,
  AlertTriangle,
} from 'lucide-react';
import { Button } from '../../../../components/ui/Button';
import { Input } from '../../../../components/ui/Input';
type CourseModule = any;

// Zod Schema
const moduleFormSchema = z
  .object({
    title: z
      .string()
      .min(3, { message: 'Module title must be at least 3 characters' })
      .max(120, { message: 'Title cannot exceed 120 characters' }),
    description: z
      .string()
      .max(500, { message: 'Description cannot exceed 500 characters' })
      .optional()
      .default(''),
    status: z.enum(['draft', 'published', 'scheduled']),
    scheduledAt: z.string().optional(),
    accessType: z.enum(['standard', 'demo']),
    unlockRule: z.enum([
      'immediate',
      'previous_module',
      'specific_date',
      'days_after_enrollment',
      'manual',
    ]),
    unlockDate: z.string().optional(),
    unlockAfterDays: z.coerce.number().optional(),
    durationHours: z.coerce.number().min(0).max(99).default(0),
    durationMinutes: z.coerce.number().min(0).max(59).default(0),
  })
  .refine(
    (data) => {
      if (data.status === 'scheduled' && !data.scheduledAt) {
        return false;
      }
      return true;
    },
    { message: 'Scheduled date is required when status is scheduled', path: ['scheduledAt'] }
  )
  .refine(
    (data) => {
      if (data.unlockRule === 'specific_date' && !data.unlockDate) {
        return false;
      }
      return true;
    },
    { message: 'Unlock date is required when unlock rule is set to specific date', path: ['unlockDate'] }
  );

export type ModuleFormValues = z.infer<typeof moduleFormSchema>;

interface ModuleFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmitModule: (data: Omit<CourseModule, 'uuid' | 'courseUuid' | 'sortOrder' | 'createdAt' | 'updatedAt' | 'lessonUuids'>) => void;
  initialModule?: CourseModule | null;
}

export const ModuleFormModal: React.FC<ModuleFormModalProps> = ({
  isOpen,
  onClose,
  onSubmitModule,
  initialModule,
}) => {
  const isEditing = Boolean(initialModule);
  const [isSubmittingLoading, setIsSubmittingLoading] = useState(false);
  const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);

  // Calculate default hours and mins
  const totalMins = initialModule?.durationMinutes || 0;
  const initialHours = Math.floor(totalMins / 60);
  const initialMinutes = totalMins % 60;

  const {
    register,
    handleSubmit,
    watch,
    reset,
    formState: { errors, isDirty },
  } = useForm<ModuleFormValues>({
    resolver: zodResolver(moduleFormSchema) as any,
    defaultValues: {
      title: initialModule?.title || '',
      description: initialModule?.description || '',
      status: initialModule?.status || 'draft',
      scheduledAt: initialModule?.scheduledAt || '',
      accessType: initialModule?.accessType || 'standard',
      unlockRule: initialModule?.unlockRule || 'immediate',
      unlockDate: initialModule?.unlockDate || '',
      unlockAfterDays: initialModule?.unlockAfterDays || 1,
      durationHours: initialHours,
      durationMinutes: initialMinutes,
    },
  });

  const descriptionValue = watch('description') || '';
  const statusValue = watch('status');
  const unlockRuleValue = watch('unlockRule');

  // Reset form when initialModule changes
  useEffect(() => {
    if (isOpen) {
      const mins = initialModule?.durationMinutes || 0;
      reset({
        title: initialModule?.title || '',
        description: initialModule?.description || '',
        status: initialModule?.status || 'draft',
        scheduledAt: initialModule?.scheduledAt || '',
        accessType: initialModule?.accessType || 'standard',
        unlockRule: initialModule?.unlockRule || 'immediate',
        unlockDate: initialModule?.unlockDate || '',
        unlockAfterDays: initialModule?.unlockAfterDays || 1,
        durationHours: Math.floor(mins / 60),
        durationMinutes: mins % 60,
      });
      setShowUnsavedWarning(false);
    }
  }, [isOpen, initialModule, reset]);

  // Handle Escape key press
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isOpen) {
        handleRequestClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, isDirty]);

  // Prevent background body scrolling when modal is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  const handleRequestClose = () => {
    if (isDirty) {
      setShowUnsavedWarning(true);
    } else {
      onClose();
    }
  };

  const handleConfirmDiscard = () => {
    setShowUnsavedWarning(false);
    onClose();
  };

  const onFormSubmit = (data: ModuleFormValues) => {
    setIsSubmittingLoading(true);
    const calculatedDuration = (data.durationHours || 0) * 60 + (data.durationMinutes || 0);

    setTimeout(() => {
      onSubmitModule({
        title: data.title,
        description: data.description || '',
        status: data.status,
        scheduledAt: data.status === 'scheduled' ? data.scheduledAt : undefined,
        accessType: data.accessType,
        unlockRule: data.unlockRule,
        unlockDate: data.unlockRule === 'specific_date' ? data.unlockDate : undefined,
        unlockAfterDays: data.unlockRule === 'days_after_enrollment' ? data.unlockAfterDays : undefined,
        durationMinutes: calculatedDuration,
      });

      setIsSubmittingLoading(false);
      reset();
      onClose();
    }, 400);
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 overflow-y-auto font-sans">
        {/* Overlay Backdrop */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          onClick={handleRequestClose}
          className="fixed inset-0 bg-[#0F172A]/60 backdrop-blur-xs transition-opacity"
        />

        {/* Modal Window Container */}
        <motion.div
          initial={{ opacity: 0, scale: 0.96, y: 16 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.96, y: 16 }}
          transition={{ type: 'spring', duration: 0.25, bounce: 0 }}
          className="relative z-10 w-full sm:max-w-xl max-h-[92vh] bg-white rounded-[20px] shadow-2xl border border-[#E2E8F0] flex flex-col overflow-hidden text-left text-xs"
        >
          {/* Header */}
          <div className="p-4 sm:p-5 bg-white border-b border-[#E2E8F0] flex items-center justify-between shrink-0 sticky top-0 z-20">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-blue-50 text-[#2563EB] flex items-center justify-center font-bold shrink-0 border border-blue-100">
                <Layers className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-semibold text-[#0F172A] text-base">
                  {isEditing ? 'Edit Module Settings' : 'Create New Course Module'}
                </h3>
                <p className="text-[12px] text-[#64748B] font-medium">
                  {isEditing ? 'Update module settings and access rules.' : 'Structure curriculum content into organized learning chapters.'}
                </p>
              </div>
            </div>

            <button
              type="button"
              onClick={handleRequestClose}
              className="w-8 h-8 rounded-lg text-[#64748B] hover:text-[#0F172A] hover:bg-slate-100 flex items-center justify-center transition-colors cursor-pointer"
            >
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Form Scrollable Body */}
          <form onSubmit={handleSubmit(onFormSubmit as any)} className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-5 no-scrollbar">
            {/* 1. MODULE TITLE */}
            <div className="space-y-1.5">
              <label className="block text-[12px] font-semibold text-[#0F172A]">
                Module Title <span className="text-rose-500">*</span>
              </label>
              <Input
                {...register('title')}
                autoFocus
                placeholder="Enter module title (e.g. Module 1: Server Components)"
                className={`w-full font-semibold text-xs h-10 bg-white border-[#E2E8F0] rounded-xl focus:border-[#2563EB] ${
                  errors.title ? 'border-rose-500 focus:border-rose-500' : ''
                }`}
              />
              {errors.title && (
                <p className="text-[11px] text-rose-500 font-medium">{errors.title.message}</p>
              )}
            </div>

            {/* 2. MODULE DESCRIPTION WITH CHARACTER COUNTER */}
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <label className="block text-[12px] font-semibold text-[#0F172A]">
                  Module Description <span className="text-[#64748B] font-normal">(Optional)</span>
                </label>
                <span
                  className={`text-[11px] font-medium ${
                    descriptionValue.length > 450 ? 'text-amber-600' : 'text-[#64748B]'
                  }`}
                >
                  {descriptionValue.length} / 500
                </span>
              </div>
              <textarea
                {...register('description')}
                rows={3}
                placeholder="Brief description outlining learning objectives of this module..."
                className={`w-full p-3 bg-white border rounded-xl font-normal text-[#0F172A] text-xs focus:outline-none focus:border-[#2563EB] resize-none ${
                  errors.description ? 'border-rose-500' : 'border-[#E2E8F0]'
                }`}
              />
              {errors.description && (
                <p className="text-[11px] text-rose-500 font-medium">{errors.description.message}</p>
              )}
            </div>

            {/* 3. MODULE STATUS & ACCESS TYPE */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5 p-4 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
              <div className="space-y-1">
                <label className="block text-[11px] font-semibold text-[#0F172A]">Module Status</label>
                <select
                  {...register('status')}
                  className="w-full h-9 px-3 bg-white border border-[#E2E8F0] rounded-lg font-semibold text-[#0F172A] text-xs focus:outline-none focus:border-[#2563EB]"
                >
                  <option value="draft">Draft (Hidden from students)</option>
                  <option value="published">Published (Visible immediately)</option>
                  <option value="scheduled">Scheduled (Publish on date)</option>
                </select>
              </div>

              {statusValue === 'scheduled' && (
                <div className="space-y-1">
                  <label className="block text-[11px] font-semibold text-[#0F172A]">Scheduled Date</label>
                  <Input
                    type="datetime-local"
                    {...register('scheduledAt')}
                    className={`w-full h-9 font-semibold text-[#2563EB] bg-white border-[#E2E8F0] ${
                      errors.scheduledAt ? 'border-rose-500' : ''
                    }`}
                  />
                  {errors.scheduledAt && (
                    <p className="text-[11px] text-rose-500 font-medium">{errors.scheduledAt.message}</p>
                  )}
                </div>
              )}

              <div className="space-y-1">
                <label className="block text-[11px] font-semibold text-[#0F172A]">Access Type</label>
                <select
                  {...register('accessType')}
                  className="w-full h-9 px-3 bg-white border border-[#E2E8F0] rounded-lg font-semibold text-[#0F172A] text-xs focus:outline-none focus:border-[#2563EB]"
                >
                  <option value="standard">Standard Enrolled Module</option>
                  <option value="demo">Free Demo (Public Preview)</option>
                </select>
              </div>
            </div>

            {/* 4. MODULE UNLOCK RULES */}
            <div className="space-y-3 p-4 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
              <h4 className="font-semibold text-[#0F172A] text-xs flex items-center gap-1.5">
                <Lock className="w-4 h-4 text-[#2563EB]" />
                Module Locking & Prerequisite Rule
              </h4>

              <div className="space-y-1">
                <select
                  {...register('unlockRule')}
                  className="w-full h-9 px-3 bg-white border border-[#E2E8F0] rounded-lg font-semibold text-[#0F172A] text-xs focus:outline-none focus:border-[#2563EB]"
                >
                  <option value="immediate">Unlock Immediately</option>
                  <option value="previous_module">Unlock After Previous Module Completion</option>
                  <option value="specific_date">Unlock On Specific Date</option>
                  <option value="days_after_enrollment">Unlock X Days After Enrollment</option>
                  <option value="manual">Unlock Manually by Instructor</option>
                </select>
              </div>

              {unlockRuleValue === 'specific_date' && (
                <div className="space-y-1 pt-1">
                  <label className="block text-[11px] font-semibold text-[#0F172A]">Unlock Date</label>
                  <Input
                    type="date"
                    {...register('unlockDate')}
                    className={`w-full h-9 font-semibold text-[#2563EB] bg-white border-[#E2E8F0] ${
                      errors.unlockDate ? 'border-rose-500' : ''
                    }`}
                  />
                  {errors.unlockDate && (
                    <p className="text-[11px] text-rose-500 font-medium">{errors.unlockDate.message}</p>
                  )}
                </div>
              )}

              {unlockRuleValue === 'days_after_enrollment' && (
                <div className="space-y-1 pt-1">
                  <label className="block text-[11px] font-semibold text-[#0F172A]">Days After Enrollment</label>
                  <Input
                    type="number"
                    min={1}
                    max={365}
                    {...register('unlockAfterDays')}
                    className="w-full h-9 font-semibold text-[#2563EB] bg-white border-[#E2E8F0]"
                  />
                </div>
              )}
            </div>

            {/* 5. ESTIMATED DURATION */}
            <div className="space-y-2 p-4 bg-[#F8FAFC] rounded-xl border border-[#E2E8F0]">
              <label className="block text-[11px] font-semibold text-[#0F172A] flex items-center gap-1.5">
                <Clock className="w-4 h-4 text-[#2563EB]" />
                Estimated Module Duration <span className="text-[#64748B] font-normal">(Optional)</span>
              </label>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <span className="text-[10px] font-medium text-[#64748B]">Hours</span>
                  <Input
                    type="number"
                    min={0}
                    max={99}
                    {...register('durationHours')}
                    className="w-full h-9 font-semibold text-[#0F172A] bg-white border-[#E2E8F0]"
                  />
                </div>
                <div className="space-y-1">
                  <span className="text-[10px] font-medium text-[#64748B]">Minutes</span>
                  <Input
                    type="number"
                    min={0}
                    max={59}
                    {...register('durationMinutes')}
                    className="w-full h-9 font-semibold text-[#0F172A] bg-white border-[#E2E8F0]"
                  />
                </div>
              </div>
            </div>

            {/* Submit Actions Footer */}
            <div className="flex items-center justify-end gap-2.5 pt-4 border-t border-[#E2E8F0] shrink-0 sticky bottom-0 bg-white min-h-[44px]">
              <Button type="button" variant="outline" onClick={handleRequestClose} className="h-10 px-4 text-[#0F172A] border-[#E2E8F0] bg-white text-xs font-semibold">
                Cancel
              </Button>
              <Button
                type="submit"
                isLoading={isSubmittingLoading}
                loadingText="Processing..."
                leftIcon={<Check className="w-4 h-4 stroke-[3]" />}
                className="bg-[#2563EB] hover:bg-[#1D4ED8] text-white font-semibold h-10 px-5 rounded-xl shadow-xs text-xs cursor-pointer"
              >
                {isEditing ? 'Save Changes' : 'Create Module'}
              </Button>
            </div>
          </form>
        </motion.div>

        {/* Unsaved Changes Confirmation Modal */}
        {showUnsavedWarning && (
          <div className="fixed inset-0 z-60 flex items-center justify-center p-4 bg-[#0F172A]/50 backdrop-blur-xs">
            <div className="w-full max-w-md bg-white rounded-2xl p-5 border border-[#E2E8F0] shadow-2xl space-y-4 text-left">
              <div className="flex items-center gap-3 text-amber-600 font-semibold text-sm">
                <AlertTriangle className="w-5 h-5 shrink-0 text-amber-500" />
                <span>Discard Unsaved Changes?</span>
              </div>
              <p className="text-[12px] text-[#64748B]">
                You have unsaved edits in this module configuration form. Are you sure you want to discard them?
              </p>
              <div className="flex items-center justify-end gap-2 pt-3 border-t border-[#E2E8F0]">
                <Button variant="outline" size="sm" onClick={() => setShowUnsavedWarning(false)}>
                  Keep Editing
                </Button>
                <Button size="sm" onClick={handleConfirmDiscard} className="bg-rose-600 hover:bg-rose-700 text-white font-semibold">
                  Discard Changes
                </Button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AnimatePresence>
  );
};

import React, { useState } from 'react';
import {
  UploadCloud,
  Film,
  Globe,
  Layers,
  ExternalLink,
  Check,
  Info,
  RefreshCw,
  XCircle,
  Lock,
  PlayCircle,
  FileText,
  Sparkles,
  CheckCircle2,
} from 'lucide-react';
import { Button } from '../../../../components/ui/Button';
import { Input } from '../../../../components/ui/Input';
import type { UnlockRuleType } from '../../../../types/curriculum.types';

export type VideoSourceType =
  | 'direct'
  | 'youtube'
  | 'vimeo'
  | 'bunny'
  | 's3'
  | 'cloudflare'
  | 'gdrive'
  | 'external';

export type VideoDeliveryMode = 'standard' | 'adaptive';
export type UploadStatus = 'waiting' | 'uploading' | 'processing' | 'ready' | 'failed' | 'cancelled';
export type CompletionMode = 'manual' | 'playback_end' | 'watch_percent' | 'watch_time' | 'full_completion';

interface VideoLessonSettingsProps {
  lesson: any;
  onSaveLesson: (updated: any) => void;
}

export const VideoLessonSettings: React.FC<VideoLessonSettingsProps> = ({
  lesson,
  onSaveLesson,
}) => {
  // 1. Video Source State
  const [sourceType, setSourceType] = useState<VideoSourceType>(
    ((lesson as any).videoSource as VideoSourceType) || 'direct'
  );
  const [externalUrl, setExternalUrl] = useState((lesson as any).videoUrl || '');

  // 2. Direct File Delivery Mode & Upload State
  const [deliveryMode, setDeliveryMode] = useState<VideoDeliveryMode>('standard');
  const [uploadStatus, setUploadStatus] = useState<UploadStatus>('ready');
  const [uploadProgress, setUploadProgress] = useState(100);
  const [processingProgress, setProcessingProgress] = useState(100);
  const [selectedFile, setSelectedFile] = useState<{ name: string; sizeMb: number } | null>({
    name: 'react19_deepdive_lecture.mp4',
    sizeMb: 450,
  });

  // 3. Video Details State
  const [title, setTitle] = useState(lesson.title);
  const [shortDesc, setShortDesc] = useState('Comprehensive video tutorial explaining React 19 RSC and Actions.');
  const [fullDesc, setFullDesc] = useState('In this video lesson, we deep-dive into React 19 architecture, Server Components, Action hooks, and optimistic UI updates.');
  const [thumbnailUrl, setThumbnailUrl] = useState('https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=600&auto=format&fit=crop&q=80');
  const [captionsUrl, setCaptionsUrl] = useState('');
  const [transcriptText, setTranscriptText] = useState('Welcome to React 19 Server Components deep dive session...');
  const [durationMinutes, setDurationMinutes] = useState(lesson.durationMinutes || 15);
  const [isDemo, setIsDemo] = useState(lesson.isDemo || false);
  const [allowDownload, setAllowDownload] = useState(false);
  const [preventSkipping, setPreventSkipping] = useState(true);
  const [resumePlayback, setResumePlayback] = useState(true);
  const [playbackSpeedControl, setPlaybackSpeedControl] = useState(true);
  const [autoPlayNext, setAutoPlayNext] = useState(true);
  const [watermark, setWatermark] = useState(true);
  const [deviceRestrictions, setDeviceRestrictions] = useState<'none' | 'mobile_only' | 'desktop_only' | 'restrict_tv'>('none');

  // 4. Video Completion Settings State
  const [completionMode, setCompletionMode] = useState<CompletionMode>('watch_percent');
  const [minWatchPercentPreset, setMinWatchPercentPreset] = useState<number | 'custom'>((lesson.unlockRule as any)?.minWatchPercent || 80);
  const [customWatchPercent, setCustomWatchPercent] = useState<number>(85);
  const [minWatchTimeMinutes, setMinWatchTimeMinutes] = useState<number>(10);
  const [_minWatchTimeSeconds, _setMinWatchTimeSeconds] = useState<number>(0);
  const [allowRewinding, setAllowRewinding] = useState(true);
  const [unlockNextAfterCompletion, setUnlockNextAfterCompletion] = useState(true);

  // 5. Unlock Rules State
  const [unlockType, setUnlockType] = useState<UnlockRuleType>((lesson.unlockRule as any)?.type || 'min_watch_percent');
  const [unlockScheduledDate, setUnlockScheduledDate] = useState((lesson.unlockRule as any)?.scheduledDate || '2026-09-01');
  const [unlockDaysAfterEnrollment, setUnlockDaysAfterEnrollment] = useState((lesson.unlockRule as any)?.daysAfterEnrollment || 3);

  // Calculated Effective Watch Percentage
  const effectiveWatchPercent = minWatchPercentPreset === 'custom' ? customWatchPercent : minWatchPercentPreset;

  // Pre-Upload Media Credit Breakdown Calculation (NO storage quota displayed)
  const fileSizeMb = selectedFile ? selectedFile.sizeMb : 450;
  const estUploadCredits = Math.max(0.1, Math.round((fileSizeMb / 100) * 10) / 10);
  const estProcessingCredits = deliveryMode === 'adaptive' ? 1.5 : 0;
  const totalEstMediaCredits = Math.round((estUploadCredits + estProcessingCredits) * 10) / 10;

  // Form Validation State
  const [titleError, setTitleError] = useState('');
  const [urlError, setUrlError] = useState('');

  // Handle Simulate Upload
  const handleSimulateUpload = () => {
    setUploadStatus('uploading');
    setUploadProgress(0);
    setProcessingProgress(0);

    const uploadInterval = setInterval(() => {
      setUploadProgress((prev) => {
        if (prev >= 100) {
          clearInterval(uploadInterval);
          if (deliveryMode === 'adaptive') {
            setUploadStatus('processing');
            const procInterval = setInterval(() => {
              setProcessingProgress((proc) => {
                if (proc >= 100) {
                  clearInterval(procInterval);
                  setUploadStatus('ready');
                  return 100;
                }
                return proc + 20;
              });
            }, 300);
          } else {
            setUploadStatus('ready');
          }
          return 100;
        }
        return prev + 25;
      });
    }, 250);
  };

  const handleCancelUpload = () => {
    setUploadStatus('cancelled');
    setUploadProgress(0);
    setProcessingProgress(0);
  };

  const handleRetryUpload = () => {
    handleSimulateUpload();
  };

  const handleFileDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      const sizeMb = Math.round(file.size / (1024 * 1024));
      setSelectedFile({ name: file.name, sizeMb });
      handleSimulateUpload();
    }
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const sizeMb = Math.round(file.size / (1024 * 1024));
      setSelectedFile({ name: file.name, sizeMb });
      handleSimulateUpload();
    }
  };

  const handleSave = () => {
    let valid = true;
    if (!title.trim()) {
      setTitleError('Video title is required');
      valid = false;
    } else {
      setTitleError('');
    }

    if (sourceType !== 'direct' && !externalUrl.trim()) {
      setUrlError('Valid external URL or video identifier is required');
      valid = false;
    } else {
      setUrlError('');
    }

    if (!valid) return;

    onSaveLesson({
      ...lesson,
      title,
      description: shortDesc,
      videoSource: sourceType === 'direct' ? 'upload' : (sourceType as any),
      videoUrl: sourceType === 'direct' ? 'https://assets.cubixskill.com/videos/react19.mp4' : externalUrl,
      durationMinutes,
      isDemo,
      unlockRule: {
        type: unlockType,
        minWatchPercent: effectiveWatchPercent,
        scheduledDate: unlockScheduledDate,
        daysAfterEnrollment: unlockDaysAfterEnrollment,
      } as any,
    });
  };

  return (
    <div className="space-y-6 text-left text-xs">
      {/* ========================================================================= */}
      {/* 1. VIDEO SOURCE PROVIDER SELECTION */}
      {/* ========================================================================= */}
      <div className="space-y-3 p-4 bg-slate-50/80 rounded-2xl border border-slate-200/80">
        <div className="flex items-center justify-between">
          <h4 className="font-extrabold text-slate-900 text-xs uppercase tracking-wider text-blue-950 flex items-center gap-1.5">
            <Film className="w-4 h-4 text-blue-600" />
            1. Select Video Source
          </h4>
          <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded-full border border-slate-200">
            Feature: Video Lessons
          </span>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          {[
            { id: 'direct', label: 'Direct File Upload', icon: UploadCloud },
            { id: 'youtube', label: 'YouTube', icon: Globe },
            { id: 'vimeo', label: 'Vimeo', icon: Globe },
            { id: 'bunny', label: 'Bunny Stream', icon: Layers },
            { id: 'cloudflare', label: 'Cloudflare Stream', icon: Film },
            { id: 's3', label: 'AWS S3', icon: Film },
            { id: 'gdrive', label: 'Google Drive', icon: Globe },
            { id: 'external', label: 'External URL', icon: ExternalLink },
          ].map((src) => {
            const Icon = src.icon;
            const isSelected = sourceType === src.id;
            return (
              <button
                key={src.id}
                type="button"
                onClick={() => setSourceType(src.id as VideoSourceType)}
                className={`p-2.5 rounded-xl border text-[11px] font-extrabold flex items-center gap-2 transition-all cursor-pointer ${
                  isSelected
                    ? 'bg-blue-600 text-white border-blue-600 shadow-sm'
                    : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-100 hover:border-slate-300'
                }`}
              >
                <Icon className={`w-3.5 h-3.5 ${isSelected ? 'text-white' : 'text-slate-400'}`} />
                <span className="truncate">{src.label}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* ========================================================================= */}
      {/* 2. DIRECT FILE UPLOAD WORKFLOW VS EXTERNAL PROVIDERS */}
      {/* ========================================================================= */}
      {sourceType === 'direct' ? (
        <div className="space-y-4 p-4 bg-white rounded-2xl border border-slate-200/80 shadow-2xs">
          <div className="flex items-center justify-between">
            <h4 className="font-extrabold text-slate-900 text-xs uppercase tracking-wider text-blue-950 flex items-center gap-1.5">
              <UploadCloud className="w-4 h-4 text-blue-600" />
              2. Video Delivery Mode Selection
            </h4>
            <span className="text-[10px] font-extrabold text-blue-700 bg-blue-50 px-2.5 py-0.5 rounded-full border border-blue-200">
              Media Credits Meter Only
            </span>
          </div>

          {/* Delivery Mode Cards: Standard vs Adaptive */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {/* Option 1: Standard Upload */}
            <div
              onClick={() => setDeliveryMode('standard')}
              className={`p-4 rounded-2xl border transition-all cursor-pointer flex flex-col justify-between space-y-3 ${
                deliveryMode === 'standard'
                  ? 'bg-blue-50/70 border-blue-600 ring-2 ring-blue-600/20'
                  : 'bg-white border-slate-200 hover:border-slate-300'
              }`}
            >
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <span className="font-extrabold text-slate-900 text-xs">Standard Upload</span>
                  <div
                    className={`w-4 h-4 rounded-full border flex items-center justify-center ${
                      deliveryMode === 'standard'
                        ? 'border-blue-600 bg-blue-600 text-white'
                        : 'border-slate-300'
                    }`}
                  >
                    {deliveryMode === 'standard' && <Check className="w-3 h-3 stroke-[3]" />}
                  </div>
                </div>
                <p className="text-[11px] text-slate-500 font-medium leading-relaxed">
                  Play the uploaded video in its original uploaded format.
                </p>
              </div>

              <ul className="text-[10px] space-y-1 font-semibold text-slate-600 pt-2 border-t border-slate-200/60">
                <li className="flex items-center gap-1.5"><Check className="w-3 h-3 text-emerald-600" /> Faster processing</li>
                <li className="flex items-center gap-1.5"><Check className="w-3 h-3 text-emerald-600" /> Lower media credit cost</li>
                <li className="flex items-center gap-1.5 text-slate-400">• No automatic quality conversion</li>
                <li className="flex items-center gap-1.5 text-slate-400">• No adaptive bitrate streaming</li>
                <li className="flex items-center gap-1.5"><Check className="w-3 h-3 text-blue-600" /> Suitable for normal course videos</li>
